const row = $('Get row(s) in sheet').first().json;
const urls = String(row['Image URL'] || '').split(',').map(s => s.trim()).filter(Boolean);
if (!urls.length) throw new Error('Kolom Image URL kosong untuk baris ini');
return urls.map((u, i) => ({ json: { image_url: u, index: i, total: urls.length } }));

const ids = items.map(i => i.json.id).filter(Boolean);
if (!ids.length) throw new Error('Tidak ada child container yang terbuat');
return [{ json: { children: ids.join(',') } }];

const m = $json.message || {};
const ALLOWED_CHATS = new Set([5331390153, 231668649]);
if (!m.chat || !ALLOWED_CHATS.has(m.chat.id) || (m.from && m.from.is_bot)) return [];
const photo = Array.isArray(m.photo) && m.photo.length ? m.photo[m.photo.length - 1].file_id : '';
const text = String(m.text || m.caption || '').trim();
if (text.startsWith('/')) return [];
if (!text && !photo) return [];
const rep = (m.reply_to_message && (m.reply_to_message.text || m.reply_to_message.caption)) || '';
return [{ json: { chat_id: m.chat.id, text, photo_file_id: photo, has_photo: !!photo, is_plan_reply: rep.startsWith('📋 Rencana konten'), reply_to_text: rep.slice(0, 300) } }];

const e = $('Msg - Ekstrak').first().json;
const logRows = $('Cari Revisi').all().map(i => i.json);
const revRows = logRows.filter(r => String(r.Status || '') === 'menunggu arahan revisi');
const today = $now.toFormat('yyyy-MM-dd');
const pendRows = logRows.filter(r => String(r.Status || '') === 'menunggu approval' && String(r.Tanggal || '') === today && r['Message ID']);
const rev = revRows.length ? revRows[revRows.length - 1] : (pendRows.length ? pendRows[pendRows.length - 1] : null);
const ovRows = $input.all().map(i => i.json).filter(r => ['menunggu', 'new'].includes(String(r.Status || '').trim().toLowerCase()) && /^T\d+$/.test(String(r.Timestamp || '')) && Date.now() - Number(String(r.Timestamp).slice(1)) < 2 * 3600 * 1000);
const plan = ovRows.length ? ovRows[ovRows.length - 1] : null;
let ref = '';
try { ref = 'https://drive.google.com/uc?export=download&id=' + $('Drive - Simpan Referensi').first().json.id; } catch (x) {}
const mode = (e.is_plan_reply || plan) ? 'plan' : (rev ? 'revisi' : 'baru');
const urls = rev ? String(rev['Image URL'] || '').split(',').filter(Boolean) : [];
const ctx = rev ? { tema: rev.Tema, slot: rev.Slot, tanggal: rev.Tanggal, jumlah_slide: urls.length || 1, format_visual: urls.length > 1 ? 'carousel' : 'single', caption_sebelumnya: rev['Caption IG'] } : null;
const SYS = "Kamu adalah "otak" asisten pembuat konten sosial media untuk akun jasa iklan digital (TikTok Ads, Shopee Ads, Meta CPAS) yang dikelola lewat Telegram. Tugasmu menafsirkan pesan user menjadi instruksi terstruktur untuk pipeline yang membuat copywriting dan gambar.

Input berupa JSON: mode, pesan_user, ada_gambar_referensi, konteks_revisi, konteks_rencana.
- mode "plan": user memberi arahan untuk rencana konten yang sedang menunggu. Kalau user menyebut topik/tema baru, isi "tema". Kalau hanya memberi arahan gaya/isi, kosongkan "tema" supaya tema kalender tetap dipakai.
- mode "revisi": ada preview konten yang belum diapprove (lihat konteks_revisi). User mungkin langsung mengetik komentar tanpa menekan tombol Revisi. Anggap pesan sebagai revisi untuk konten itu, KECUALI user jelas meminta topik/konten yang sama sekali baru, maka intent "konten_baru". Pertahankan tema kecuali user jelas minta ganti. "arahan" harus menjelaskan apa yang diubah dan apa yang dipertahankan.
- mode "baru": user minta konten baru di luar jadwal. Isi "tema" dengan topik yang dimaksud.
- Kalau pesan hanya sapaan, pertanyaan, atau bukan permintaan konten, intent "ngobrol" dan balas singkat serta tanya konten apa yang diinginkan.

Pilih intent dengan tepat, ini menentukan apa yang dibuat ulang:
- "revisi_copy": user hanya ingin mengubah teks/caption (kata, nada, panjang, ajakan). Gambar dipertahankan persis.
- "revisi_visual": user hanya ingin mengubah gambar/visual/warna/layout. Caption dipertahankan persis.
- "revisi_semua": perubahan menyangkut keduanya, atau tidak jelas.
- "ganti_tema": user ingin topik yang sama sekali berbeda untuk konten ini.
- "konten_baru": user meminta konten lain di luar konten yang sedang direvisi (hanya di mode revisi).
- "tambah_arahan": arahan tambahan untuk rencana (mode plan).

Balas HANYA dengan JSON valid:
{"intent":"revisi_copy|revisi_visual|revisi_semua|ganti_tema|konten_baru|tambah_arahan|ngobrol","tema":"","pilar":"","format_visual":"single atau carousel atau kosong","jumlah_slide":0,"arahan":"instruksi jelas untuk copywriter dan desainer, bahasa Indonesia, tanpa mengulang pesan mentah","balasan":"1-2 kalimat konfirmasi santai ke user, bahasa Indonesia","aturan_baru":""}

ATURAN BELAJAR: kalau koreksi user bersifat PERMANEN dan berlaku untuk konten-konten berikutnya (mis. logo harus persis, CTA hanya di slide tertentu, gaya bahasa, warna, hal yang dilarang), tulis satu kalimat aturan umum yang singkat dan jelas di "aturan_baru" (tanpa menyebut tema konten tertentu). Kalau koreksi hanya untuk konten ini saja, kosongkan "aturan_baru".

Aturan: format single = 1 slide, carousel = 2 sampai 10 slide. Kosongkan field yang tidak diubah user. Kalau ada gambar referensi, sebut di arahan bahwa gambar itu dipakai sebagai acuan visual. Jangan mengarang data atau angka. Nada balasan santai, bukan formal.";
const user = JSON.stringify({ mode, pesan_user: e.text, ada_gambar_referensi: !!ref, konteks_revisi: mode === 'revisi' ? ctx : null, konteks_rencana: mode === 'plan' ? (plan ? { tema_sudah_diatur: plan.Tema || '', arahan_sebelumnya: plan.Instruksi || '' } : e.reply_to_text) : null });
return [{ json: { mode, ref, rev, plan, body: { model: 'gpt-5.4-mini', response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: user }] } } }];

const ctx = $('Siapkan Otak').first().json;
const e = $('Msg - Ekstrak').first().json;
let out;
try { out = JSON.parse($json.choices[0].message.content); } catch (x) { out = { intent: 'tambah_arahan', arahan: e.text, balasan: 'Oke, arahannya aku catat ya.' }; }
const rev = ctx.rev;
const plan = ctx.plan;
const arahan = out.arahan || e.text;
const fmt = out.format_visual || (plan ? plan['Format Visual'] : '') || '';
const jml = Number(out.jumlah_slide) || Number(plan ? plan['Jumlah Slide'] : 0) || 0;
return [{ json: {
  mode: (ctx.mode === 'revisi' && out.intent === 'konten_baru') ? 'baru' : ctx.mode, chat_id: e.chat_id, ref: ctx.ref || (plan ? plan.Gambar : '') || '',
  intent: out.intent || 'tambah_arahan', aturan_baru: String(out.aturan_baru || '').trim(),
  tema: out.tema || (plan ? plan.Tema : '') || '', pilar: out.pilar || (plan ? plan.Pilar : '') || '',
  format_visual: fmt, jumlah_slide: jml,
  arahan, balasan: out.balasan || 'Oke, diproses ya.',
  plan_ts: plan ? plan.Timestamp : '',
  plan_instruksi: plan && plan.Instruksi ? plan.Instruksi + ' | ' + arahan : arahan,
  rev_message_id: rev ? rev['Message ID'] : '', rev_tanggal: rev ? rev.Tanggal : '', rev_slot: rev ? rev.Slot : '',
  rev_tema: rev ? rev.Tema : '', rev_caption: rev ? String(rev['Caption IG'] || '') : '', rev_images: rev ? String(rev['Image URL'] || '') : '',
  rev_slides: rev ? String(rev['Image URL'] || '').split(',').filter(Boolean).length : 0
} }];

const j = $json;
const isRev = j.mode === 'revisi';
let revisi = 'semua';
if (isRev) {
  if (j.intent === 'revisi_copy' && j.rev_images) revisi = 'copy';
  else if (j.intent === 'revisi_visual' && j.rev_caption) revisi = 'visual';
}
const fmt = j.format_visual || (isRev ? (j.rev_slides > 1 ? 'carousel' : 'single') : 'single');
let jml = j.jumlah_slide || (isRev ? (j.rev_slides || 1) : 1);
if (fmt === 'single') jml = 1;
const tema = j.tema || (isRev ? j.rev_tema : j.arahan);
const instruksi = isRev
  ? 'REVISI dari versi sebelumnya. Caption sebelumnya: "' + j.rev_caption.slice(0, 600) + '". Arahan revisi: ' + j.arahan
  : j.arahan;
return [{ json: {
  chat_id: j.chat_id, balasan: j.balasan, mode: j.mode, rev_message_id: j.rev_message_id,
  Tanggal: isRev && j.rev_tanggal ? j.rev_tanggal : $now.toFormat('yyyy-MM-dd'),
  Slot: isRev && j.rev_slot ? j.rev_slot : ($now.hour < 12 ? 'pagi' : 'sore'),
  Pilar: j.pilar || 'umum', Tema: tema, 'Format Visual': fmt, 'Jumlah Slide': jml,
  Instruksi: instruksi, Gambar: j.ref || '',
  Revisi: revisi, CaptionLama: isRev ? j.rev_caption : '', GambarLama: isRev ? j.rev_images : ''
} }];

const rows = $input.all().map(i => i.json).filter(r => ['menunggu', 'new'].includes(String(r.Status || '').trim().toLowerCase()) && r.ResumeUrl);
const r = rows.length ? rows[rows.length - 1] : null;
return [{ json: { url: r ? r.ResumeUrl : '' } }];
